#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <IRremote.h>

// Инициализация экрана (адрес 0x27, 16 столбцов, 2 строки)
LiquidCrystal_I2C lcd(0x27, 16, 2);

// Пины устройств (оставляем без изменений)
const int IR_PIN = 2;
const int GARLAND_PIN = 7;
const int LED_PINS[] = {8, 9, 10, 11}; 

bool garlandState = LOW; 

void setup() {
  // Настройка пинов светодиодов и гирлянды
  pinMode(GARLAND_PIN, OUTPUT);
  for (int i = 0; i < 4; i++) {
    pinMode(LED_PINS[i], OUTPUT);
  }

  // Запуск ИК-приемника
  IrReceiver.begin(IR_PIN, ENABLE_LED_FEEDBACK);

  // Настройка экрана
  lcd.init();
  lcd.backlight();

  // Верхняя строка
  lcd.setCursor(0, 0);
  lcd.print("GAPOU IO ITAM   ");

  // Обновление нижней строки
  updateDisplay();
}

void loop() {
  // 1. Проверяем ИК-датчик
  if (IrReceiver.decode()) {
    if (IrReceiver.decodedIRData.decodedRawData > 0) {
      garlandState = !garlandState;        
      digitalWrite(GARLAND_PIN, garlandState);
      updateDisplay();                     
      delay(300);                          
    }
    IrReceiver.resume(); 
  }

  // 2. Анимация 4 статус-диодов
  int speedDelay = garlandState ? 100 : 300; 

  for (int i = 0; i < 4; i++) {
    digitalWrite(LED_PINS[i], HIGH);
    delay(speedDelay);
    digitalWrite(LED_PINS[i], LOW);
  }
}

// Функция обновления статуса на экране
void updateDisplay() {
  lcd.setCursor(0, 1); 
  if (garlandState == HIGH) {
    lcd.print("Garland: ACTIVE "); 
  } else {
    lcd.print("Garland: OFF    ");
  }
}

